 s=json.loads((repo/p['draftDirectory']/'sources.json').read_text());ext.append({'id':p['citationKey'],'displayName':p['title'],'authors':'OpenAI','version':p['version']+'; fixed commit '+I['sourceCommit'],'sourceUrl':p['sourceUrl'],'pdfPages':p['pdfPages'],'checkedLocations':[{'printedPage':str(n),'pdfPage':n} for n in range(1,p['pdfPages']+1)]})
